// Strip de partes dinâmicas do system prompt (geradas por switches).
// Usado para: (1) salvar apenas o base no preset, (2) getConfig() retornar só o base
// para que buildMessages() adicione as partes dinâmicas sem duplicação.
function _stripDynamicParts(content) {
if (!content || typeof content !== 'string') return content || '';
const markers = [
'═══ FORMATO DE EDIÇÃO:',
'═══════════ MAPA DE AÇÕES (LEIA PRIMEIRO) ═══════════',
'═══ WORKFLOWS OPCIONAIS ═══',
'═══ OPERAÇÕES DE ARQUIVO (FILE OPS) ═══',
'═══ FERRAMENTAS / PLUGINS DISPONÍVEIS (TOOL CALLING) ═══',
'═══ PROMPT EXTRA ATIVO',
'═══ PRIORIDADE MÁXIMA — MODO EDITOR DE ARQUIVOS ATIVO ═══',
'═══ AGENTE DOM DA PÁGINA (PAGE ACTION) ═══',
];
for (const marker of markers) {
const idx = content.indexOf(marker);
if (idx >= 0) {
const cutIdx = idx >= 2 && content[idx - 1] === '\n' && content[idx - 2] === '\n' ? idx - 2 : idx;
return content.substring(0, cutIdx).trimEnd();
}
}
return content;
}
