if (ch === '/' && str[i + 1] === '/') {
const nl = str.indexOf('\n', i);
i = nl < 0 ? str.length : nl;
continue;
}
if (ch === '/' && str[i + 1] === '*') {
const end = str.indexOf('*/', i + 2);
i = end < 0 ? str.length : end + 1;
continue;
}
if (ch === open) depth++;
