//   module.exports = { 'foo': ..., "bar baz": ... }        → ['foo']
//   module.exports = { foo: { a: 1, b: 2 }, bar }          → ['foo', 'bar']  (aninhamento ok)
//   module.exports.foo = ...                               → ['foo']
//   exports.foo = ...                                      → ['foo']
