'new', 'return', 'this', 'class', 'const', 'let', 'var', 'if', 'else',
'for', 'while', 'do', 'switch', 'case', 'break', 'continue', 'try',
'catch', 'finally', 'throw', 'typeof', 'instanceof', 'in', 'of'
