new RegExp('(?:async\\s+)?function\\s+' + escaped + '\\s*\\(([^)]*)\\)', 'm'),
new RegExp('(?:const|let|var)\\s+' + escaped + '\\s*=\\s*(?:async\\s+)?(?:function\\s*)?\\(([^)]*)\\)', 'm'),
new RegExp('(?:const|let|var)\\s+' + escaped + '\\s*=\\s*(?:async\\s+)?([A-Za-z_$][\\w$]*)\\s*=>', 'm')
