const content = await IDBFileStore.get(f.idbKey || f.id);
if (content == null) return { ok: false, reason: 'Conteúdo não encontrado no IndexedDB' };
f.content = content;
f.contentPreview = content.slice(0, 2000);
f.size = content.length;
f.storage = 'gm';
