c: 'c', h: 'c', cs: 'csharp', php: 'php', rb: 'ruby', go: 'go',
rs: 'rust', swift: 'swift', kt: 'kotlin', scala: 'scala', r: 'r',
m: 'objectivec', mm: 'objectivec', sql: 'sql', sh: 'bash', ps1: 'powershell',
html: 'html', htm: 'html', css: 'css', scss: 'scss', sass: 'sass',
less: 'less', xml: 'xml', json: 'json', yaml: 'yaml', yml: 'yaml',
md: 'markdown', txt: 'text', csv: 'csv', log: 'text'
