function normalizePromptName(name) {
return String(name || '').replace(/\s+/g, ' ').trim().slice(0, 80) || 'Sem nome';
}
function addPromptReducer(state, payload, env = {}) {
const prompts = Array.isArray(state?.prompts) ? state.prompts.slice() : [];
const normalizedName = normalizePromptName(payload?.name || 'Sem nome');
let finalName = normalizedName;
const existingNames = new Set(prompts.map(p => p.name));
if (existingNames.has(finalName)) {
let n = 2;
while (existingNames.has(`${normalizedName} (${n})`)) n++;
finalName = `${normalizedName} (${n})`;
}
const now = env.now || Date.now();
const item = {
id: payload.id || (env.generateId ? env.generateId() : ('p_' + now.toString(36))),
name: finalName,
content: String(payload?.content == null ? '' : payload.content),
groupId: payload?.groupId || 'default',
version: now
};
const next = prompts.concat(item);
return { prompts: next, activeId: item.id, item, changed: true };
}
function updatePromptReducer(state, id, fields, env = {}) {
const prompts = Array.isArray(state?.prompts) ? state.prompts.slice() : [];
let changed = false;
let updated = null;
const now = env.now || Date.now();
const next = prompts.map(p => {
if (p.id !== id) return p;
let copy = { ...p };
if (fields && fields.name !== undefined) {
const newName = normalizePromptName(fields.name);
if (copy.name !== newName) { copy.name = newName; changed = true; }
}
if (fields && fields.content !== undefined) {
const newContent = String(fields.content);
if (copy.content !== newContent) { copy.content = newContent; changed = true; }
}
if (fields && fields.groupId !== undefined && copy.groupId !== fields.groupId) {
copy.groupId = fields.groupId;
changed = true;
}
if (changed) copy.version = now;
updated = copy;
return copy;
});
return { prompts: next, activeId: state?.activeId || null, item: updated, changed };
}
