// Função orquestradora pura — substituição da validateConfig monolítica.
// Recebe cfg + opcionalmente um getActiveProviderId pra evitar dependência circular.
function validateProviderConfig(cfg, activeProviderId) {
const url = String(cfg.apiUrl || '').trim();
const basic = _isUrlBasic(url);
if (!basic.ok) return basic;
const isLocal = _isUrlLocal(url);
const ctx = {
url,
apiKey: cfg.apiKey || '',
isLocal,
cfg
};
// Provider ativo: parâmetro explícito > cfg.provider > 'openrouter'
const provId = activeProviderId || cfg.provider || 'openrouter';
const validator = ProviderValidators[provId] || ProviderValidators._generic;
return validator(ctx);
}
