// PARTE 11 — GERENCIADOR DE ESTADO DA UI
// ===================================================================
// v2.21-fix: Infere path a partir do contexto (texto antes do bloco SEARCH/REPLACE).
// Estratégias de inferência:
//   1. Procura "path=X", "file=X", "arquivo X" no texto precedente
//   2. Procura padrão de filename com extensão (ex: "calc.html", "script.js")
//   3. Extrai <title> de conteúdo HTML
//   4. Extrai extensão do conteúdo (html, js, css, py, etc.)
//   5. Fallback: "_desconhecido"
function _inferPathFromContext(precedingText, searchContent, replaceContent) {
const prec = String(precedingText || '');
// 1) path= ou file= explícito no texto precedente.
// Captura até o fim da linha (depois trim) para suportar nomes COM ESPAÇO,
// ex: "path=calculator (1).html". A versão antiga parava no 1º espaço e
// falhava nesses casos → a edição não casava com o arquivo anexado.
const pathKvMatch = prec.match(/(?:path|file|filename|arquivo)\s*[:=]\s*["']?([^\n\r"'`]+?\.\w{1,10})["']?\s*$/im)
|| prec.match(/(?:path|file|filename|arquivo)\s*[:=]\s*["']?([^\s"'`]+\.\w{1,10})["']?/i);
if (pathKvMatch) return pathKvMatch[1].trim();
// 2) Filename com extensão mencionado no texto (último antes do bloco)
const fnMatches = [...prec.matchAll(/\b([a-zA-Z0-9_\-][a-zA-Z0-9_\-\.]*\.(?:html?|css|js|ts|jsx?|tsx|py|java|json|xml|md|txt|yml|yaml|sh|bash|c|cpp|h|rb|php|go|rs|sql|vue|svelte|astro))\b/gi)];
if (fnMatches.length > 0) return fnMatches[fnMatches.length - 1][1];
// Helper: slugify com suporte a acentos (á→a, ç→c, etc.)
const slugify = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50);
// 3) <title> em conteúdo HTML → nome_do_title.html
const titleMatch = String(replaceContent || '').match(/<title[^>]*>([^<]+)<\/title>/i);
if (titleMatch) {
const slug = slugify(titleMatch[1].trim());
if (slug) return slug + '.html';
}
// 4) Detecta linguagem pelo conteúdo e gera nome genérico
const fullContent = String(replaceContent || searchContent || '');
// HTML: doctype, <html>, <head>, <body>, <div> etc.
if (/<\!doctype\s+html/i.test(fullContent) || /<html[\s>]/i.test(fullContent) || /<head[\s>]/i.test(fullContent) || /<body[\s>]/i.test(fullContent)) return 'novo-arquivo.html';
// CSS: seletores, propriedades, @rules
if (/@import|@media|@keyframes|@font-face|:root\s*\{|^\{?\s*\.[a-z]/m.test(fullContent) || /^\s*[.#@a-z][a-z0-9-]*\s*\{/im.test(fullContent) || /\{\s*[a-z-]+\s*:/m.test(fullContent)) return 'novo-arquivo.css';
// JavaScript: function, const, let, var, class, import, export, arrow functions
if (/^(?:import\s|export\s|const\s|let\s|var\s|function\s|class\s|module\.exports)/m.test(fullContent) || /=>\s*[{(]/m.test(fullContent) || /console\.(log|warn|error|info)/m.test(fullContent)) return 'novo-arquivo.js';
// Python: def, import, from, class, if __name__
if (/^(?:def\s|import\s|from\s|class\s|if\s+__name__)/m.test(fullContent) || /print\s*\(/m.test(fullContent)) return 'novo-arquivo.py';
// JSON: { ou [ no início
if (/^[\[{]/m.test(fullContent) && /"[a-z_]+"\s*:/m.test(fullContent)) return 'novo-arquivo.json';
// Markdown: headings, listas, links
if (/^#{1,6}\s/m.test(fullContent) || /^\s*[-*]\s/m.test(fullContent)) return 'novo-arquivo.md';
// 5) Fallback — tenta detectar pelo contexto (arquivo mencionado sem extensão)
const contextMentions = prec.match(/\b(?:arquivo|file|script|style|página|page)\s+(?:chamad[oa]\s+)?["']?([a-zA-Z0-9_\-]+)["']?/i);
if (contextMentions) {
const name = contextMentions[1].toLowerCase();
if (/script|js|javascript/i.test(prec)) return name + '.js';
if (/style|css|estilo/i.test(prec)) return name + '.css';
if (/página|page|html/i.test(prec)) return name + '.html';
return name + '.txt';
}
return 'novo-arquivo.txt';
}
