// Configura o drop universal no painel inteiro (não só na aba Arquivos)
setupGlobalDropZone() {
let dragCounter = 0;
// Detecta drag de arquivos (ignora drag interno)
const hasFiles = (e) => {
const t = e.dataTransfer;
if (!t) return false;
if (t.types) {
for (const type of t.types) {
if (type === 'Files' || type === 'application/x-moz-file') return true;
}
}
return false;
};
__aaLifecycle.on(this.panel, 'dragenter', (e) => {
if (!hasFiles(e)) return;
e.preventDefault();
dragCounter++;
this.dropOverlay.classList.add('active');
});
__aaLifecycle.on(this.panel, 'dragover', (e) => {
if (!hasFiles(e)) return;
e.preventDefault();
e.dataTransfer.dropEffect = 'copy';
});
__aaLifecycle.on(this.panel, 'dragleave', (e) => {
if (!hasFiles(e)) return;
dragCounter--;
if (dragCounter <= 0) {
dragCounter = 0;
this.dropOverlay.classList.remove('active');
}
});
__aaLifecycle.on(this.panel, 'drop', async (e) => {
if (!hasFiles(e)) return;
e.preventDefault();
e.stopPropagation();
dragCounter = 0;
this.dropOverlay.classList.remove('active');
const files = e.dataTransfer?.files;
if (files && files.length > 0) {
await this.handleFiles(files);
// Foca o input pra usuário já mandar mensagem
this.switchTab('chat');
this.inputEl?.focus();
}
});
// Previne abrir o arquivo no navegador se soltar fora do painel também
__aaLifecycle.on(window, 'dragover', (e) => {
if (hasFiles(e)) e.preventDefault();
});
__aaLifecycle.on(window, 'drop', (e) => {
// Se soltou dentro do shadow host mas não no painel (improvável), também previne
if (hasFiles(e) && this.panel.contains(e.target)) e.preventDefault();
});
}
// Sistema de redimensionamento por handles. dir = n/s/e/w/ne/nw/se/sw
makeResizable(panel, handle, dir) {
let isResizing = false;
let startX, startY, startW, startH, startLeft, startTop;
const MIN_W = 360, MIN_H = 320;
const onMove = (e) => {
if (!isResizing) return;
const dx = e.clientX - startX;
const dy = e.clientY - startY;
let newW = startW, newH = startH, newLeft = startLeft, newTop = startTop;
if (dir.includes('e')) newW = Math.max(MIN_W, startW + dx);
if (dir.includes('w')) {
const w = Math.max(MIN_W, startW - dx);
newLeft = startLeft + (startW - w);
newW = w;
}
if (dir.includes('s')) newH = Math.max(MIN_H, startH + dy);
if (dir.includes('n')) {
const h = Math.max(MIN_H, startH - dy);
newTop = startTop + (startH - h);
newH = h;
}
panel.style.width  = newW + 'px';
panel.style.height = newH + 'px';
panel.style.left   = newLeft + 'px';
panel.style.top    = newTop + 'px';
panel.style.right  = 'auto';
panel.style.bottom = 'auto';
};
const onUp = () => {
if (!isResizing) return;
isResizing = false;
panel.classList.remove('resizing');
};
__aaLifecycle.on(handle, 'mousedown', (e) => {
e.preventDefault();
e.stopPropagation();
isResizing = true;
panel.classList.add('resizing');
const rect = panel.getBoundingClientRect();
startX = e.clientX; startY = e.clientY;
startW = rect.width; startH = rect.height;
startLeft = rect.left; startTop = rect.top;
});
__aaLifecycle.on(document, 'mousemove', onMove);
__aaLifecycle.on(document, 'mouseup', onUp);
}
