// ====================================================================
// BUG 3 — Construtor de PATCH (unified diff) para o botão "Baixar"
// ====================================================================
// Gera um arquivo .patch no formato unified diff (compatível com git apply,
// patch -p0, code review tools). Header com path + ts + estratégia.
// Linhas removidas (SEARCH) prefixadas com "-", adicionadas (REPLACE) com "+".
_buildEditPatch(edit) {
const path = String(edit.path || 'unknown');
const search = String(edit.search || '');
const replace = String(edit.replace || '');
const ts = new Date().toISOString();
const searchLines = search.split('\n');
const replaceLines = replace.split('\n');
let patch = `# Patch gerado por PHGBR chat\n`;
patch += `# Arquivo: ${path}\n`;
patch += `# Data: ${ts}\n`;
if (edit._id) patch += `# Edit ID: ${edit._id}\n`;
if (edit.inferred) patch += `# Origem: auto-detectado\n`;
patch += `#\n`;
patch += `--- a/${path}\n`;
patch += `+++ b/${path}\n`;
// Hunk header simplificado (não temos line-numbers reais do arquivo aqui).
// Usamos "?" como marca de posição — humans/tools leem ok, git apply pode
// preferir --no-numbered, mas patch -p0 aceita tranquilo.
patch += `@@ -1,${searchLines.length} +1,${replaceLines.length} @@\n`;
for (const l of searchLines) patch += '-' + l + '\n';
for (const l of replaceLines) patch += '+' + l + '\n';
return patch;
}
