const textExt = new Set([
'js','mjs','cjs','ts','tsx','jsx','py','java','cpp','cc','cxx','c','h','hpp','cs','php','rb','go','rs','swift','kt','kts','scala','r','sql','sh','bash','zsh','fish','ps1',
'html','htm','css','scss','sass','less','xml','json','jsonl','yaml','yml','toml','ini','env','md','mdx','txt','csv','tsv','log','dockerfile','gitignore','gitattributes','editorconfig',
'vue','svelte','astro','graphql','gql','prisma','gradle','properties','lock','svg'
]);
