renameSelectedFiles() {
const ids = Array.from(this.selectedFiles || []);
if (ids.length === 0) { this.toast && this.toast('Nenhum arquivo selecionado', 'warn'); return; }
if (ids.length === 1) { this.renameFile(ids[0]); return; }
const prefix = prompt(`Prefixo para renomear ${ids.length} arquivos (serão numerados preservando extensão):`, 'arquivo');
if (prefix == null) return;
const clean = String(prefix).trim();
if (!clean || /[\\/\x00-\x1f]/.test(clean)) { this.toast && this.toast('Prefixo inválido', 'error'); return; }
const existing = new Set(FileManager.list().filter(f => !this.selectedFiles.has(f.id)).map(f => f.name));
let i = 1, renamed = 0;
for (const id of ids) {
const f = FileManager.get(id); if (!f) continue;
const dot = f.name.lastIndexOf('.');
const ext = dot > 0 ? f.name.slice(dot) : '';
let candidate = `${clean} ${String(i).padStart(2, '0')}${ext}`;
while (existing.has(candidate)) { i++; candidate = `${clean} ${String(i).padStart(2, '0')}${ext}`; }
if (FileManager.rename(id, candidate)) { existing.add(candidate); renamed++; i++; }
}
this.renderFileList();
this.toast && this.toast(`${renamed} arquivo(s) renomeado(s)`, 'success');
}
deleteSelectedFiles() {
const ids = Array.from(this.selectedFiles || []);
if (ids.length === 0) { this.toast && this.toast('Nenhum arquivo selecionado', 'warn'); return; }
if (!confirm(`Excluir ${ids.length} arquivo(s) selecionado(s)?`)) return;
let n = 0;
for (const id of ids) {
if (typeof ToolRegistry !== 'undefined') { try { ToolRegistry.deactivatePlugin(id); } catch (_) {} try { ToolRegistry.savePluginState(id, { active: false }); } catch (_) {} }
if (FileManager.remove(id)) n++;
if (this.attachedFiles) this.attachedFiles.delete(id);
if (this.currentFileId === id) this.closeFileEditor();
}
this.selectedFiles.clear();
this._persistAttachments && this._persistAttachments();
this.renderAttachmentBar && this.renderAttachmentBar();
this.renderFileList();
this.toast && this.toast(`${n} arquivo(s) excluído(s)`, 'info');
}
_zipNameFromLabel(label) {
return String(label || 'arquivos').replace(/[^\w\-.]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80) || 'arquivos';
}
async downloadFilesAsZip(files, zipName) {
files = (files || []).filter(Boolean);
for (const f of files) { if (f && f.storage === 'idb' && !f.content) await FileManager.ensureContentLoaded(f.id); }
if (files.length === 0) { this.toast && this.toast('Nenhum arquivo para baixar', 'warn'); return; }
const blob = __aaZip.makeBlob(files);
const url = URL.createObjectURL(blob);
const a = document.createElement('a');
a.href = url;
a.download = (this._zipNameFromLabel(zipName).replace(/\.zip$/i, '') || 'arquivos') + '.zip';
a.click();
setTimeout(() => URL.revokeObjectURL(url), 500);
this.toast && this.toast(`ZIP gerado com ${files.length} arquivo(s)`, 'success');
}
downloadSelectedFilesZip() {
const files = Array.from(this.selectedFiles || []).map(id => FileManager.get(id)).filter(Boolean);
this.downloadFilesAsZip(files, 'arquivos-selecionados');
}
downloadActiveFileGroupZip() {
const active = this._getActiveFileGroup();
let files = this._visibleFilesForCurrentFilter();
let label = 'todos-arquivos';
if (active === '__ungrouped') label = 'sem-grupo';
else if (active) { const g = FileGroupManager.get(active); label = g ? g.name : 'grupo'; }
this.downloadFilesAsZip(files, label);
}
