// === DUPLICAR === cópia com sufixo " (cópia)" — sem anexar ao chat
// === PLUGIN TOGGLE (Fase X) === abre modal de revisão ou desativa
async togglePlugin(fileId) {
// Bug 4 fix: debounce contra double-fire do <label><input/></label>
// (o navegador pode disparar click no label + click sintético no input).
// Também previne cliques duplos acidentais do usuário.
const now = Date.now();
this._lastToggleAt = this._lastToggleAt || {};
if (this._lastToggleAt[fileId] && (now - this._lastToggleAt[fileId]) < 350) {
console.log('[ORChat] togglePlugin: ignorando double-fire em', fileId);
return;
}
this._lastToggleAt[fileId] = now;
const file = FileManager.get(fileId);
if (!file) return;
// Bug 4 fix: snapshot do estado ANTES de qualquer ação, para garantir
// que decidimos baseado no estado real (não em um render stale do DOM).
const wasActive = ToolRegistry.isPluginActive(fileId);
console.log('[ORChat] togglePlugin', { fileId, name: file.name, wasActive });
// Se já ativo, desativa direto (NUNCA abre modal nesse caminho)
if (wasActive) {
ToolRegistry.deactivatePlugin(fileId);
ToolRegistry.savePluginState(fileId, { active: false });
this.toast && this.toast(`🔌 Plugin "${file.name}" desativado`, 'info');
this.renderFileList();
return;
}
// Guard contra modal duplicado — porém SEMPRE limpa modais presos antes.
// Se já existe um modal de revisão REAL no DOM, não abre outro.
// Caso contrário (flag presa de uma sessão/erro anterior), limpa tudo e segue.
{
const open = this.shadow ? this.shadow.querySelector('[data-role="plugin-review-modal"]') : null;
if (open && this._pluginReviewModalOpen) {
console.log('[ORChat] Modal de revisão já aberto — ignorando');
return;
}
// Remove qualquer modal preso e reseta a flag (defesa contra estado travado).
try {
if (this.shadow) this.shadow.querySelectorAll('[data-role="plugin-review-modal"]').forEach(el => { try { el.remove(); } catch (_) {} });
} catch (_) {}
this._pluginReviewModalOpen = false;
}
// Parse das funções (Fase FF: aceita @tool, exports.tools E module.exports)
let parsed;
try {
parsed = ToolRegistry.parsePluginSource(file.content);
} catch (e) {
console.error('[ORChat] parsePluginSource erro:', e);
this.toast && this.toast('Erro ao analisar o plugin: ' + (e && e.message || e), 'error');
return;
}
if (!parsed || parsed.length === 0) {
this.toast && this.toast(
'Nenhuma função detectada. Use UM destes 3 formatos:\n' +
'  1) /** @tool nome - descrição */ function nome() {...}\n' +
'  2) exports.tools = [{name, description, fn}]\n' +
'  3) module.exports = { minha_funcao }',
'warn',
{ duration: 6000 }
);
return;
}
// Feedback imediato: confirma ao usuário que o clique foi registrado e o
// modal de revisão vai abrir (evita a sensação de "não acontece nada").
this.toast && this.toast(`Revisando plugin "${file.name}" (${parsed.length} função(ões))...`, 'info', { duration: 1500 });
this._openPluginReviewModal(file, parsed);
}
