renderConversationList() {
this._ensureConvPanel();
const query = (this.convSearchInput?.value || '').toLowerCase().trim();
let convs = ConversationManager.list();
if (query) {
convs = convs.filter(c => {
if ((c.title || '').toLowerCase().includes(query)) return true;
// busca também no conteúdo das mensagens
return String(c.searchText || '').toLowerCase().includes(query) || (c.messages || []).some(m => (m.content || '').toLowerCase().includes(query));
});
}
this.convListEl.replaceChildren();
if (convs.length === 0) {
this.convListEl.appendChild(__domCreateEl('div', {
className: 'or-conv-empty',
textContent: query ? 'Nenhuma conversa encontrada' : 'Nenhuma conversa ainda. Comece a digitar uma mensagem!'
}));
return;
}
const activeId = ConversationManager.activeId;
for (const c of convs) {
const item = __domCreateEl('div', {
className: 'or-conv-item' + (c.id === activeId ? ' active' : ''),
onclick: () => { this.loadConversation(c.id); this.toggleConversationList(false); }
});
const titleEl = __domCreateEl('div', { className: 'or-conv-item-title', textContent: c.title });
const dateStr = new Date(c.updated).toLocaleString();
const metaEl = __domCreateEl('div', { className: 'or-conv-item-meta', textContent: `${Number.isFinite(c.messageCount) ? c.messageCount : ((c.messages || []).length)} msgs · ${dateStr}` });
const renameBtn = __domCreateEl('button', {
className: 'or-conv-item-btn',
title: 'Renomear',
onclick: (e) => { e.stopPropagation(); this.renameConversation(c.id); }
});
renameBtn.appendChild(svgIcon('edit', 11));
// Botão Duplicar conversa (clona histórico completo numa nova conversa)
const dupBtn = __domCreateEl('button', {
className: 'or-conv-item-btn',
title: 'Duplicar conversa (cópia completa do histórico)',
onclick: (e) => { e.stopPropagation(); this.duplicateConversation(c.id); }
});
dupBtn.appendChild(svgIcon('copy', 11));
const delBtn = __domCreateEl('button', {
className: 'or-conv-item-btn danger',
title: 'Excluir',
onclick: (e) => { e.stopPropagation(); this.deleteConversation(c.id); }
});
delBtn.appendChild(svgIcon('trash', 11));
const actions = __domCreateEl('div', { className: 'or-conv-item-actions' });
actions.append(renameBtn, dupBtn, delBtn);
item.append(titleEl, metaEl, actions);
this.convListEl.appendChild(item);
}
}
toggleConversationList(forceState) {
this._ensureConvPanel();
const isOpen = this.convPanelEl.classList.contains('open');
const shouldOpen = (typeof forceState === 'boolean') ? forceState : !isOpen;
if (shouldOpen) {
this.renderConversationList();
this.convPanelEl.classList.add('open');
if (this.convSearchInput) { this.convSearchInput.value = ''; this.convSearchInput.focus(); }
} else {
this.convPanelEl.classList.remove('open');
}
}
