// Fuzzy match simples: cada char da query precisa aparecer na string em ordem.
// Pontua por: proximidade dos chars, match em início de palavra, match exato no label.
_fuzzyScore(query, target) {
const q = query.toLowerCase();
const t = target.toLowerCase();
if (!q) return 1;
if (t.includes(q)) {
const idx = t.indexOf(q);
return 100 + (idx === 0 ? 50 : 0) - idx * 0.5;
}
let score = 0;
let lastIdx = -1;
let consecutive = 0;
for (let i = 0; i < q.length; i++) {
const c = q[i];
const idx = t.indexOf(c, lastIdx + 1);
if (idx === -1) return 0;
score += 10;
if (idx === lastIdx + 1) { consecutive++; score += consecutive * 2; }
else { consecutive = 0; }
// Bonus se for início de palavra
if (idx === 0 || t[idx - 1] === ' ' || t[idx - 1] === '-' || t[idx - 1] === '_') score += 5;
lastIdx = idx;
}
return score;
}
