importAllSettings() {
const input = document.createElement('input');
input.type = 'file';
input.accept = '.json,application/json';
input.onchange = async (e) => {
const f = e.target.files?.[0];
if (!f) return;
try {
const text = await f.text();
const dump = JSON.parse(text);
if (!dump || dump.__schema !== 'orchat-export-v1') {
this.toast('Arquivo inválido: schema desconhecido', 'error');
return;
}
if (!confirm(`Importar backup?\n\n• ${(dump.prompts || []).length} prompts\n• ${(dump.conversations || []).length} conversas\n• ${(dump.files || []).length} arquivos\n\nIsso vai MESCLAR com seus dados atuais.`)) return;
// Settings (não sobrescreve API_KEY)
const s = dump.settings || {};
if (s.api_url) __aaStorage.set(STORAGE_KEYS.API_URL, s.api_url);
if (s.model) __aaStorage.set(STORAGE_KEYS.MODEL, s.model);
if (s.preferred_provider !== undefined) __aaStorage.set(STORAGE_KEYS.PREFERRED_PROVIDER, s.preferred_provider);
if (s.theme) __aaStorage.set(STORAGE_KEYS.THEME, s.theme);
if (s.aggressive_retry !== undefined) __aaStorage.set(STORAGE_KEYS.AGGRESSIVE_RETRY, s.aggressive_retry);
if (s.free_only !== undefined) __aaStorage.set(`${SCRIPT_ID}_free_only`, s.free_only);
// Prompts — mescla, evita duplicatas por id
if (Array.isArray(dump.prompts)) {
const existing = new Set(PromptManager.list().map(p => p.id));
for (const p of dump.prompts) {
if (!p?.id || existing.has(p.id)) continue;
PromptManager.prompts.push({ id: p.id, name: p._normalizeName ? p._normalizeName(p.name) : String(p.name || 'Sem nome'), content: String(p.content || '') });
}
PromptManager.saveAll();
}
// Conversas
if (Array.isArray(dump.conversations)) {
for (const c of dump.conversations) {
if (c?.id) ConversationManager.conversations.set(c.id, c);
}
ConversationManager.saveAll();
}
// Arquivos
if (Array.isArray(dump.files)) {
await FileManager.batch(async () => {
for (const f2 of dump.files) {
try { FileManager.add({ name: f2.name, type: f2.type, size: f2.size, content: f2.content }); } catch (_) {}
}
});
}
this.loadSettings();
this.renderFileList();
this.renderConversationList();
this._renderPromptGroupBar && this._renderPromptGroupBar();
this._renderPromptSelect && this._renderPromptSelect();
this.toast('✓ Backup importado e mesclado', 'success');
} catch (err) {
this.toast('Erro ao importar: ' + err.message, 'error');
}
};
input.click();
}
