// Extrai todos os blocos ```...``` de um texto e junta com separador
_extractCodeBlocks(text) {
const blocks = [];
const re = /```([\w-]*)\n?([\s\S]*?)```/g;
let m;
while ((m = re.exec(text)) !== null) {
// Ignora search-replace (são instruções, não código pra copiar)
if (/^search[-_]?replace|^edit|^diff|^patch/i.test(m[1])) continue;
if (/<{3,}\s*(SEARCH|ORIGINAL|BEFORE)/i.test(m[2])) continue;
blocks.push(m[2].trimEnd());
}
return blocks.join('\n\n');
}
