// Estado do monitor: já avisou crítico? Já bloqueou?
// Usado pra mostrar toast 1x por threshold ao cruzar (evita spam).
_scheduleTokenMonitorUpdate() {
if (this._tokenMonitorRaf) return;
this._tokenMonitorRaf = setTimeout(() => {
this._tokenMonitorRaf = null;
this._updateTokenMonitor();
}, 200);
}
// Atualiza a barra. Idempotente — pode ser chamado a qualquer momento.
_updateTokenMonitor() {
const bar = this.tokenMonitorBar;
if (!bar || !bar.__refs) return;
const refs = bar.__refs;
try {
const cfg = OpenRouterClient.getConfig();
const meta = ModelMetaRegistry.get(cfg.provider, cfg.model);
const ctxLimit = meta && meta.ctx ? meta.ctx : null;
if (!ctxLimit) {
// Sem metadados → esconde a barra
bar.style.display = 'none';
return;
}
// Coleta input + arquivos + sistema + últimas mensagens (configurável via tools, reusa)
const inputText = (this.inputEl && this.inputEl.value) || '';
const attachedContent = [];
if (this.attachedFiles && this.attachedFiles.size > 0 && typeof FileManager !== 'undefined') {
const files = FileManager.list().filter(f => this.attachedFiles.has(f.id));
for (const f of files) attachedContent.push(String(f.content || ''));
}
if (this._isPageContextOn && this._isPageContextOn()) {
try {
const pageCtx = this._getPageContextText ? this._getPageContextText(false) : this._extractPageContextText();
if (pageCtx) attachedContent.push(pageCtx);
} catch (_) {}
}
let historyMessages = [];
try {
const conv = ConversationManager.getActive && ConversationManager.getActive();
if (conv && Array.isArray(conv.messages)) {
const ctxN = Math.max(0, Math.min(50, parseInt(__aaStorage.get(STORAGE_KEYS.CHAT_CONTEXT_MSGS, '0'), 10) || 0));
historyMessages = ctxN > 0 ? conv.messages.filter(m => m.role === 'user' || m.role === 'ai').slice(-ctxN) : [];
}
} catch (_) {}
const estimated = TokenEstimator.fromRequest({
inputText,
attachedFilesContent: attachedContent,
historyMessages,
systemPrompt: cfg.systemPrompt
});
const classification = TokenEstimator.classify(estimated, ctxLimit);
const pct = Math.min(100, classification.percent);
const estStr = estimated.toLocaleString();
const limitStr = ctxLimit.toLocaleString();
const pctStr = classification.percent.toFixed(classification.percent < 10 ? 1 : 0) + '%';
refs.labelEl.textContent = `~${estStr} / ${limitStr} tok`;
refs.labelEl.style.color = classification.color;
refs.barInner.style.width = pct.toFixed(1) + '%';
refs.barInner.style.background = classification.color;
refs.hintEl.textContent = classification.icon
? `${classification.icon} ${pctStr} — ${classification.message}`
: pctStr;
refs.hintEl.style.color = classification.color;
bar.style.display = 'flex';
bar.classList.toggle('over-limit', classification.level === 'over');
// Toast 1x ao cruzar threshold crítico ou over
const lastLevel = this._lastTokenLevel || 'ok';
if (classification.level !== lastLevel) {
if (classification.level === 'critical' && lastLevel !== 'over') {
this.toast && this.toast(
`⚠ Contexto em ${pctStr} (${estStr}/${limitStr} tok) — próximo do limite do modelo`,
'warn', { duration: 4000 }
);
} else if (classification.level === 'over') {
this.toast && this.toast(
`🚫 Excedeu o limite (${estStr}/${limitStr} tok). Envio bloqueado — remova arquivos ou encurte a mensagem.`,
'error', { duration: 6000 }
);
}
this._lastTokenLevel = classification.level;
}
// Atualiza estado pra sendMessage saber se deve bloquear
this._tokenStateOver = (classification.level === 'over');
this._tokenStateEstimated = estimated;
this._tokenStateLimit = ctxLimit;
} catch (e) {
console.warn('[ORChat] _updateTokenMonitor error:', e);
bar.style.display = 'none';
}
}
