// Tem grupo favorito → popula dropdown
refs.pickerRow.style.display = '';
const prompts = PromptManager.listByGroup(favGroup.id) || [];
refs.select.replaceChildren();
// Primeira opção: "— Nenhum —" (não anexa nada)
