protectedText = _normalizeModelHtmlishText(protectedText);
// 2) Escapa prosa. Marcadores \u0000 sobrevivem ao escapeHtml.
let html = escapeHtml(protectedText);
// 3) Blocos de prosa.
html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');
// Listas: agrupa linhas consecutivas "- item" em <ul> válido.
html = html.replace(/((?:^- .+(?:\n|$))+)/gm, (block) => {
const items = block.trim().split('\n')
.filter(l => /^- /.test(l))
.map(l => '<li>' + l.slice(2) + '</li>')
.join('');
return items ? '<ul>' + items + '</ul>' : block;
});
// Inline styles de prosa — bold antes de italic.
html = html.replace(/\*\*([^*\n]+?)\*\*/g, '<strong>$1</strong>');
html = html.replace(/(^|[^*])\*(?!\*)([^*\n]+?)\*(?!\*)/g, '$1<em>$2</em>');
// Links com esquema seguro.
html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_, label, href) => {
const rawHref = String(href || '').replace(/&amp;/g, '&').trim();
if (!/^(https?:|mailto:|#|\/)/i.test(rawHref)) return label;
return '<a href="' + href + '" target="_blank" rel="noopener noreferrer">' + label + '</a>';
});
// Quebras só na prosa; placeholders ainda não foram restaurados.
html = html.replace(/\n/g, '<br>');
// 4) Restaura blocos protegidos sem <br> interno.
html = html.replace(/\u0000ORCHAT_MD_(\d+)\u0000/g, (_, i) => placeholders[Number(i)] || '');
// 5) PÓS-PROCESSAMENTO: remove qualquer tag HTML que tenha vazado do
